import html, os
from http.server import BaseHTTPRequestHandler, HTTPServer
COLOR=os.getenv("APP_COLOR","BLUE").upper()
VERSION=os.getenv("APP_VERSION","local")
class Handler(BaseHTTPRequestHandler):
 def do_GET(self):
  if self.path=="/health":
   body=b"OK"; self.send_response(200); self.send_header("Content-Type","text/plain"); self.end_headers(); self.wfile.write(body); return
  accent="#438cff" if COLOR=="BLUE" else "#24c99a"
  page="""<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Experiment 8</title><style>*{box-sizing:border-box}body{margin:0;min-height:100vh;background:#080d18;color:#eef3ff;font-family:Arial;display:grid;place-items:center;padding:24px}.wrap{width:min(850px,100%)}.top{display:flex;justify-content:space-between;color:#9eacc4;font-size:12px;letter-spacing:2px}.card{margin-top:28px;padding:clamp(26px,6vw,56px);border:1px solid #26344d;border-radius:24px;background:linear-gradient(145deg,#121e32,#0d1525)}.tag,h1 span,.pill{color:ACCENT}.tag{font-weight:bold;letter-spacing:3px;font-size:12px}h1{font-size:clamp(38px,8vw,72px);margin:18px 0;letter-spacing:-3px}.lead{color:#aab7cc;font-size:17px;line-height:1.7}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin-top:35px}.metric{background:#0a1220;border:1px solid #26344d;border-radius:14px;padding:20px}.label{color:#8798b3;font-size:11px;letter-spacing:2px}.value{font-size:23px;font-weight:bold;margin-top:10px}.pill{display:inline-block;margin-top:28px;border:1px solid ACCENT;padding:10px 15px;border-radius:999px;font-size:12px;font-weight:bold}footer{color:#71809a;text-align:center;margin-top:24px;font-size:12px}@media(max-width:520px){.grid{grid-template-columns:1fr}}</style></head><body><main class="wrap"><div class="top"><span>DEPLOYFLOW / EXPERIMENT 08</span><span>● LIVE RESPONSE</span></div><section class="card"><div class="tag">AUTOMATED BLUE-GREEN DEPLOYMENT</div><h1>Traffic is on <span>COLOR</span>.</h1><p class="lead">This page is served by the COLOR Kubernetes environment. Jenkins verifies the inactive environment before switching production traffic.</p><div class="grid"><div class="metric"><div class="label">ACTIVE ENVIRONMENT</div><div class="value">COLOR</div></div><div class="metric"><div class="label">APPLICATION RELEASE</div><div class="value">Build VERSION</div></div><div class="metric"><div class="label">ORCHESTRATION</div><div class="value">Kubernetes / K3s</div></div><div class="metric"><div class="label">DELIVERY PIPELINE</div><div class="value">Jenkins + Docker</div></div></div><div class="pill">● HEALTH CHECK PASSED</div></section><footer>EXPERIMENT 08 · BLUE-GREEN RELEASE CONTROL · AWS EC2</footer></main></body></html>"""
  page=page.replace("ACCENT",accent).replace("COLOR",html.escape(COLOR)).replace("VERSION",html.escape(VERSION))
  body=page.encode(); self.send_response(200); self.send_header("Content-Type","text/html; charset=utf-8"); self.send_header("Content-Length",str(len(body))); self.end_headers(); self.wfile.write(body)
 def log_message(self,fmt,*args): print(fmt%args,flush=True)
HTTPServer(("0.0.0.0",8080),Handler).serve_forever()
